layouts.css:
.aha-social-proofs-badges{
  container:aha-social-proofs-badges / inline-size;
  background:var(--aha-white);
  font-family:var(--aha-font-product);
}
.aha-social-proofs-badges *{box-sizing:border-box}
.aha-social-proofs-badges__list{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--aha-space-12);padding:var(--aha-space-32) var(--aha-space-16)}
.aha-social-proofs-badges__item{display:block;width:100%;max-width:80px;border-radius:var(--aha-radius-xs)}
.aha-social-proofs-badges__item img{display:block;width:100%;height:auto}
.aha-social-proofs-badges__item--wide img{width:110%;max-width:none}
.aha-social-proofs-badges__item:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
@container aha-social-proofs-badges (max-width:767px){
  .aha-social-proofs-badges__item{aspect-ratio:80 / 81}
  .aha-social-proofs-badges__item img{height:100%;object-fit:contain}
  .aha-social-proofs-badges__item--wide img{width:110%;height:100%}
}

.aha-social-proofs-g2{
  container:aha-social-proofs-g2 / inline-size;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-social-proofs-g2 *{box-sizing:border-box}
.aha-social-proofs-g2--pale{background:var(--aha-vivid-pink-5)}
.aha-social-proofs-g2__inner{display:flex;flex-wrap:wrap;justify-content:center;align-items:center;gap:var(--aha-space-16);padding:var(--aha-space-32) var(--aha-space-16)}
.aha-social-proofs-g2__logos{display:flex;padding:var(--aha-space-8);border-radius:var(--aha-radius-lg);background:var(--aha-white)}
.aha-social-proofs-g2__logo{display:block;width:var(--aha-space-48);height:var(--aha-space-48);object-fit:contain;border-radius:var(--aha-radius-pill);background:var(--aha-white)}
.aha-social-proofs-g2__detail{display:flex;flex-direction:column;align-items:flex-start;gap:var(--aha-space-4)}
.aha-social-proofs-g2__rating{display:flex;align-items:center;gap:var(--aha-space-8)}
.aha-social-proofs-g2__score{font-size:var(--aha-size-l);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-body)}
.aha-social-proofs-g2__text{font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);letter-spacing:var(--aha-letter-spacing-paragraph);color:var(--aha-text-secondary)}
.aha-social-proofs-g2__label{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@container aha-social-proofs-g2 (max-width:479px){
  .aha-social-proofs-g2__inner{flex-direction:column}
  .aha-social-proofs-g2__detail{align-items:center}
}
